-    lua_gettable(L, -2);
+    lua_gettable(LS, -2);

     // We don't need the dissectors_table in the stack
     // After call, stack: [ error_handler_func, dissector ]
-    lua_remove(L,2);
+    lua_remove(LS,2);
+
+    wmem_register_callback(pinfo->pool, lua_pinfo_end, NULL);

     // Is the dissector a function?
-    if (lua_isfunction(L,2)) {
